/**
 * Instance-level wrapping for SDKs generated by Stainless (`openai`,
 * `@anthropic-ai/sdk`). Their methods return an APIPromise (a Promise
 * subclass with withResponse()/asResponse()/_thenUnwrap()) and stream
 * objects with private state, so neither can be swapped for a Proxy without
 * breaking tee(), toReadableStream() or instanceof checks. Instead the ways of
 * consuming the returned object are wrapped on that one instance.
 */
import { Call, observeIterator } from "./recorder.js";

type AnyFn = (...args: any[]) => any;
const WRAPPED_STREAM = Symbol.for("agentcost.stream");
export const PATCHED = Symbol.for("agentcost.instrumented");

export interface Hooks {
  /** Build the call and the params to send. Throwing here sends the call untracked. */
  begin(params: any): { call: Call; send: any; fallbackAllowed: boolean };
  /** Non-streamed result. */
  value(call: Call, value: any): void;
  /** One stream event. */
  chunk(call: Call, chunk: any): void;
  /** True if `err` means "the parameters we injected were refused". */
  refusedInjection?(err: unknown): boolean;
}

function isStream(v: any): boolean {
  return !!v && typeof v === "object" && typeof v.iterator === "function" && "controller" in v;
}

/**
 * Route every consumer of a stream (for-await, tee(), toReadableStream(), the
 * SDK's own helpers) through one observer by replacing the instance's
 * iterator factory. The object keeps its class and private state.
 */
function wrapStream(stream: any, call: Call, hooks: Hooks): any {
  if (stream[WRAPPED_STREAM]) return stream;
  Object.defineProperty(stream, WRAPPED_STREAM, { value: true, enumerable: false });
  call.setStreaming();
  const original = stream.iterator;
  stream.iterator = function () {
    return observeIterator(original.call(stream), call, (c) => hooks.chunk(call, c));
  };
  return stream;
}

function observe(result: any, call: Call, hooks: Hooks): any {
  if (isStream(result)) return wrapStream(result, call, hooks);
  try {
    hooks.value(call, result);
  } catch {
    /* observation must never break the call */
  }
  call.finish();
  return result;
}

export function wrapMethod(resource: any, method: string, hooks: Hooks): void {
  const original: AnyFn | undefined = resource?.[method];
  if (typeof original !== "function" || (original as any)[PATCHED]) return;
  const bound = original.bind(resource);

  const tracked = function agentcostTracked(params: any, ...rest: any[]) {
    let call: Call;
    let send: any;
    let fallbackAllowed: boolean;
    try {
      ({ call, send, fallbackAllowed } = hooks.begin(params));
    } catch {
      return bound(params, ...rest);
    }

    const promise: any = bound(send, ...rest);
    const refused = (err: unknown) => fallbackAllowed && !!hooks.refusedInjection?.(err);

    if (!promise || typeof promise.then !== "function") {
      // Synchronous return (unexpected): record what we can.
      return observe(promise, call, hooks);
    }
    if (typeof promise.withResponse !== "function") {
      // A custom transport returning a plain promise.
      return Promise.resolve(promise).then(
        (r) => observe(r, call, hooks),
        (e) => {
          call.finish(e);
          throw e;
        },
      );
    }

    const origThen: AnyFn = promise.then.bind(promise);
    const origThenUnwrap: AnyFn | undefined = typeof promise._thenUnwrap === "function" ? promise._thenUnwrap.bind(promise) : undefined;
    let active: any = promise;
    let settled: Promise<any> | undefined;

    const settle = (): Promise<any> => {
      settled ??= new Promise<any>((resolve, reject) => {
        origThen(resolve, reject);
      }).then(
        (data) => observe(data, call, hooks),
        (err) => {
          if (refused(err)) {
            // Resent once, exactly as the caller wrote it.
            call.meta("stream_options_rejected", true);
            active = bound(params, ...rest);
            return Promise.resolve(active).then(
              (data: any) => observe(data, call, hooks),
              (e: unknown) => {
                call.finish(e);
                throw e;
              },
            );
          }
          call.finish(err);
          throw err;
        },
      );
      return settled;
    };

    promise.then = (onF?: AnyFn, onR?: AnyFn) => settle().then(onF, onR);
    promise.catch = (onR?: AnyFn) => settle().catch(onR);
    promise.finally = (onF?: () => void) => settle().finally(onF);
    if (typeof promise.asResponse === "function") {
      const origAsResponse: AnyFn = promise.asResponse.bind(promise);
      const activeResponse = () => (active === promise ? origAsResponse() : active.asResponse());
      promise.withResponse = async () => {
        const data = await settle();
        const response = await activeResponse();
        return { data, response, request_id: response?.headers?.get?.("request-id") ?? response?.headers?.get?.("x-request-id") ?? null };
      };
      // The caller reads the raw HTTP body themselves, so usage is not
      // visible: the call is still recorded, honestly marked as missing usage.
      promise.asResponse = () =>
        origAsResponse().then((r: unknown) => {
          setTimeout(() => {
            if (!call.finished && !settled) call.finish();
          }, 0);
          return r;
        });
    }
    if (origThenUnwrap) {
      // The SDKs' own helpers (parse(), some stream helpers) consume through
      // this. No injection fallback here: the helper owns the request.
      promise._thenUnwrap = (transform: AnyFn) =>
        origThenUnwrap((data: any, props: any) => transform(observe(data, call, hooks), props));
    }
    // Failures on paths that never reach observe() (asResponse, helpers).
    const raw = promise.responsePromise;
    if (raw && typeof raw.then === "function") {
      raw.then(undefined, (err: unknown) => {
        if (!refused(err)) call.finish(err);
      });
    }
    return promise;
  };
  (tracked as any)[PATCHED] = true;
  resource[method] = tracked;
}
